jQuery(document).ready(function ($) {
$('.contact-form span.wpcf7-form-control-wrap').each(function(){
    let value = $(this).find("input").attr("placeholder");
    if(value === undefined){
      value = $(this).find("textarea").attr("placeholder");
      if(value === undefined){
        value = 'Define placeholder for your input/textarea in Contact Form 7'
      }
    }
    $(this).append('<span class="contact-form__text">'+ value + '</span><span class="contact-form__line"></span>');
  });
});
</script>"},"elements":[],"widgetType":"html"}],"isInner":true}],"isInner":true}],"isInner":false}],"isInner":false}]

[{"id":"6a92bed","elType":"section","settings":[],"elements":[{"id":"b5b810f","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"d909300","elType":"widget","settings":[],"elements":[],"widgetType":"spacer"}],"isInner":false}],"isInner":false},{"id":"27a9367","elType":"section","settings":{"margin":{"unit":"px","top":"100","right":0,"bottom":"100","left":0,"isLinked":true}},"elements":[{"id":"3b51b2f","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"2277857","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="UTF-8" />
 <meta name="viewport" content="width=device-width, initial-scale=1.0" />
 <title>Prompt Assistant</title>
 <style>
 * { box-sizing: border-box; }
 body { font-family: Arial, sans-serif; background: #f9f9f9; margin: 0; padding: 0; }
 .prompt-assistant-container {
 max-width: 600px;
 margin: 2rem auto;
 background: #fff;
 padding: 2rem;
 border-radius: 12px;
 box-shadow: 0 0 20px rgba(0,0,0,0.05);
 }
 h2 {
 text-align: center;
 margin-bottom: 1.5rem;
 color: #333;
 }
 label {
 font-weight: bold;
 display: block;
 margin-top: 1rem;
 }
 select, input {
 width: 100%;
 padding: 10px;
 margin-top: 5px;
 border-radius: 5px;
 border: 1px solid #ccc;
 }
 button {
 margin-top: 1rem;
 width: 100%;
 padding: 12px;
 background-color: #0073e6;
 color: white;
 border: none;
 border-radius: 5px;
 font-size: 1rem;
 cursor: pointer;
 }
 button:hover {
 background-color: #005bb5;
 }
 pre {
 background: #f0f0f0;
 padding: 1rem;
 margin-top: 1.5rem;
 white-space: pre-wrap;
 border-radius: 6px;
 font-size: 0.95rem;
 position: relative;
 }
 .copy-button {
 background: #28a745;
 margin-top: 0.5rem;
 }
 </style>
</head>
<body>
 <div class="prompt-assistant-container">
 <h2>🎯 Prompt Assistant</h2>

 <label for="role">Choose a Role:</label>
 <select id="role">
 <option value="copywriter">Copywriter</option>
 <option value="sales">Sales</option>
 <option value="analyst">Analyst</option>
 <option value="teacher">Teacher</option>
 </select>

 <label for="context">Task or Topic:</label>
 <input type="text" id="context" placeholder="e.g., explain blockchain to beginners" />

 <label for="format">Preferred Format:</label>
 <input type="text" id="format" placeholder="e.g., bullet points, paragraph" />

 <label for="tone">Preferred Tone:</label>
 <input type="text" id="tone" placeholder="e.g., formal, friendly, persuasive" />

 <button onclick="generatePrompt()">Generate Prompt</button>

 <pre id="output"></pre>
 <button class="copy-button" onclick="copyPrompt()">Copy Prompt</button>
 </div>

 <script>
 const roles = {
 copywriter: "Act as a senior copywriter for a tech company.",
 sales: "Act as a B2B sales rep writing a cold outreach.",
 analyst: "Act as a data analyst generating insights from reports.",
 teacher: "Act as an educational instructor explaining a topic to beginners."
 };

 function generatePrompt() {
 const role = document.getElementById("role").value;
 const context = document.getElementById("context").value;
 const format = document.getElementById("format").value;
 const tone = document.getElementById("tone").value;

 const prompt = `${roles[role]}\n\nWrite about: ${context}\nFormat it as: ${format}\nUse a ${tone} tone.`;
 document.getElementById("output").textContent = prompt;
 }

 function copyPrompt() {
 const text = document.getElementById("output").textContent;
 navigator.clipboard.writeText(text).then(() => {
 alert("✅ Prompt copied to clipboard!");
 }).catch(() => {
 alert("❌ Failed to copy prompt.");
 });
 }
 </script>
</body>
</html>
"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]
